{
  "findings": [
    {
      "check_id": "CKV2_AWS_73",
      "title": "Ensure AWS SQS uses CMK not AWS default keys for encryption",
      "resource": "aws_sqs_queue.pass2",
      "severity": "MEDIUM",
      "explanation": "The SQS queue is using AWS managed SSE, which may not be as secure as using a customer-managed key (CMK) for encryption."
    }
  ],
  "patched_code": "resource \"aws_sqs_queue\" \"pass2\" {\n  name                        = \"unencrypted-queue\"\n  sqs_managed_sse_enabled     = false\n  kms_master_key_id           = \"alias/aws/sqs\"\n}",
  "fix_summary": "Changed the SQS queue to use a KMS key for encryption instead of AWS managed SSE."
}
